lint.example-violation:
#[repr(C, align(64))]
struct BadCapsule {
    state: Mutex<u64>,  // ❌ P0 violation
}

lint.example-fix:
#[repr(C, align(64))]
struct GoodCapsule {
    state: AtomicU64,  // ✅ Lockfree
}

lint.example-violation:
#[repr(C, align(64))]
struct BadCapsule {
    state: AtomicU64,  // 8 bytes
    counter: u32,      // 4 bytes
    // Total: 12 bytes (not multiple of 64) ❌
}

lint.example-fix:
#[repr(C, align(64))]
struct GoodCapsule {
    state: AtomicU64,     // 8 bytes
    counter: u32,         // 4 bytes
    _padding: [u8; 52],   // 52 bytes padding
    // Total: 64 bytes (exact multiple) ✅
}

lint.example-violation:
#[repr(C, align(64))]
struct BadCapsule {
    state: AtomicU64,  // No generation counter ❌
}

lint.example-fix:
#[repr(C, align(64))]
struct GoodCapsule {
    state: AtomicU64,  // Lower 32: state | Upper 32: generation ✅
}

impl GoodCapsule {
    fn load_with_generation(&self) -> (u32, u32) {
        let raw = self.state.load(Ordering::Acquire);
        let state = (raw & 0xFFFF_FFFF) as u32;
        let gen = (raw >> 32) as u32;
        (state, gen)
    }
}

lint.example-violation:
#[repr(C, align(64))]
struct BadCapsule {
    counter: u64,  // Non-atomic field ❌
}

lint.example-fix:
#[repr(C, align(64))]
struct GoodCapsule {
    counter: AtomicU64,  // Atomic field ✅
}

lint.example-violation:
#[repr(C, align(64))]
struct UnverifiedCapsule {
    state: AtomicU64,
}
// ⚠️ No verification macro

lint.example-fix-manual:
#[repr(C, align(64))]
struct VerifiedCapsule {
    state: AtomicU64,
}

verify_capsule_properties!(VerifiedCapsule, 64, 8);  // ✅ Manual verification

lint.example-fix-derive:
#[derive(ComputationalCapsule)]  // ✅ Automatic verification
#[repr(C, align(64))]
struct VerifiedCapsule {
    state: AtomicU64,
}

commit-msg-hook.script:
#!/bin/bash # Commit-Msg Hook: Enforce commit message format # Location: .git/hooks/commit-msg # Framework: UCE34 Q34 (Auditability)
COMMIT_MSG_FILE=$1 COMMIT_MSG=$(cat "$COMMIT_MSG_FILE")
# Check for required tags if echo "$COMMIT_MSG" | grep -qE '^\[(TRADE SECRET|P0 FIX|P1 FIX|FEAT|FIX|REFACTOR|DOCS|TEST)\]'; then exit 0 else echo "❌ [Commit-Msg] Invalid commit message format!" echo "" echo "Required format: [TAG] Description" echo "" echo "Valid tags:" echo " [TRADE SECRET] - Trade secret code (local commits only)" echo " [P0 FIX] - P0 critical lint fix" echo " [P1 FIX] - P1 high lint fix" echo " [FEAT] - New feature" echo " [FIX] - Bug fix" echo " [REFACTOR] - Code refactoring" echo " [DOCS] - Documentation update" echo " [TEST] - Test addition/update" echo "" echo "Example: [P0 FIX] Replace Mutex with AtomicU64 in CircuitBreakerCapsule" exit 1 fi

vscode.configuration:
{
  // Rust Analyzer Configuration for clippy-capsule-verify
  // Location: .vscode/settings.json (workspace settings)

  // Enable clippy linting
  "rust-analyzer.check.command": "clippy",

  // Pass custom clippy arguments
  "rust-analyzer.check.extraArgs": [
    "--all-targets",
    "--all-features",
    "--",
    "-D", "clippy::capsule_mutex_violation",
    "-D", "clippy::capsule_unaligned_violation",
    "-D", "clippy::capsule_missing_generation",
    "-D", "clippy::capsule_non_atomic_field",
    "-W", "clippy::missing_capsule_verification"
  ],

  // Enable inline diagnostics
  "rust-analyzer.diagnostics.enable": true,
  "rust-analyzer.diagnostics.experimental.enable": true,

  // Auto-save triggers check
  "files.autoSave": "afterDelay",
  "files.autoSaveDelay": 1000,

  // Show clippy warnings in problems panel
  "rust-analyzer.diagnostics.warningsAsInfo": [
    "clippy::missing_capsule_verification"
  ],

  // Format on save
  "editor.formatOnSave": true,
  "[rust]": {
    "editor.defaultFormatter": "rust-lang.rust-analyzer"
  }
}

vscode.keyboard-shortcuts:
[
  // Quick clippy check (Ctrl+Shift+C)
  {
    "key": "ctrl+shift+c",
    "command": "workbench.action.tasks.runTask",
    "args": "Clippy Check P0"
  },
  // Full validation (Ctrl+Shift+V)
  {
    "key": "ctrl+shift+v",
    "command": "workbench.action.tasks.runTask",
    "args": "Clippy Check All"
  }
]

