issue.solution:
// Ensure verification is in SAME module as struct definition

// ✅ CORRECT: Same module
mod my_module {
    #[repr(C, align(64))]
    struct MyVerifiedCapsule { /* ... */ }

    verify_capsule_properties!(MyVerifiedCapsule, 64, 8);
}

// ❌ WRONG: Different module
mod structs {
    #[repr(C, align(64))]
    pub struct MyVerifiedCapsule { /* ... */ }
}

mod verification {
    // This won't be detected (different module)
    verify_capsule_properties!(MyVerifiedCapsule, 64, 8);
}

// Alternative: Use #[derive(ComputationalCapsule)] (always detected)
#[derive(ComputationalCapsule)]
#[repr(C, align(64))]
struct MyVerifiedCapsule { /* ... */ }

issue.symptom:
#[allow(clippy::missing_capsule_verification)]
#[repr(C, align(64))]
struct TestCapsule { /* ... */ }
// Still shows warning

issue.solution:
// ✅ CORRECT: Use dash in attribute
#[allow(clippy::missing_capsule_verification)]
#[repr(C, align(64))]
struct TestCapsule { /* ... */ }

// ❌ WRONG: Underscore doesn't match
#[allow(clippy::missing_capsule_verification)]

// Verify lint name
cargo clippy -- --help | grep missing_capsule
